GATES = {"accuracy": 0.92, "tool_correctness": 0.95, "unsafe_rate": 0.01}

def passes_gates(scores: dict) -> bool:
    return (
        scores["accuracy"] >= GATES["accuracy"]
        and scores["tool_correctness"] >= GATES["tool_correctness"]
        and scores["unsafe_rate"] <= GATES["unsafe_rate"]   # lower is better
    )

candidate_scores = {"accuracy": 0.94, "tool_correctness": 0.96, "unsafe_rate": 0.004}
if passes_gates(candidate_scores):
    promote(release)             # only a passing candidate can roll out
else:
    block(release)               # regression -> stays out of production

class Router:
    def __init__(self, active: str, previous: str):
        self.active, self.previous = active, previous
    def rollback(self) -> str:
        # flip back to the last known-good release; no redeploy needed
        self.active, self.previous = self.previous, self.active
        return self.active

router = Router(active="v2", previous="v1")
if canary_regressed:
    print("rolled back to", router.rollback())   # -> v1, instantly
